const CMD_COMBO = { WP:"b12", WK:"b34", WL:"b13", WR:"b24", LPRK:"b14", RPLK:"b23", WPLK:"b123", WPRK:"b124", LPWK:"b134", RPWK:"b234", WPWK:"b1234", LP:"b1", RP:"b2", LK:"b3", RK:"b4" };
const CMD_LABEL = { WL: "LP+LK", WR: "RP+RK" };   // アイコンの読み上げ名（WL・WR という呼び方は使わない）
const CMD_RE = /(WPWK|WPRK|WPLK|LPWK|RPWK|LPRK|RPLK|WP|WK|WL|WR|LP|RP|LK|RK)|([1-9])(\^?)|n|\./g;
function cmdIcon(cls, label) {
  const i = document.createElement("i");
  i.className = "ci ci-" + cls; i.setAttribute("role", "img"); i.setAttribute("aria-label", label);
  return i;
}
function renderCmd(el, str) {
  el.textContent = "";
  let last = 0, m, prevEnd = -1;
  const isLatin = ch => /[A-Za-z]/.test(ch || "");
  const text = t => { if (t) { const s = document.createElement("span"); s.className = "ct"; s.textContent = t; el.appendChild(s); } };
  CMD_RE.lastIndex = 0;
  while ((m = CMD_RE.exec(str))) {
    const s = m.index, e = s + m[0].length, prev = str[s - 1] || "", next = str[e] || "";
    if (m[0] === ".") { if (prevEnd === s && /[A-Za-z1-9]/.test(next)) { text(str.slice(last, s)); last = e; } continue; }
    if (m[2]) {
      if (next && next.charCodeAt(0) > 127 && next !== "）" && next !== "】" && next !== "【") continue;
      if (/レベル$/.test(str.slice(0, s))) continue;
    } else if (m[0] === "n") {
      if (isLatin(prev) || isLatin(next)) continue;
    }
    text(str.slice(last, s)); last = e; prevEnd = e;
    if (m[1]) el.appendChild(cmdIcon(CMD_COMBO[m[1]], CMD_LABEL[m[1]] || m[1]));
    else if (m[2]) {
      let d = m[2];
      if (d === "5") el.appendChild(cmdIcon("nn", "n"));
      else el.appendChild(cmdIcon((m[3] ? "h" : "d") + d, d + (m[3] ? "(ホールド)" : "")));
    } else el.appendChild(cmdIcon("nn", "n"));
  }
  text(str.slice(last));
}

/* 技表（チェックシート）のコマンド表示用。
   技データには、同時押しと順番押しの区別がない書き方（RPLK・LPRK・WPLK など、ボタンを続けて書いたもの）が混ざっている。
   ・+ でつないだボタン（RP+LK・LP+RK・LP+LK・WP+LK など）は、同時押しの1つのアイコンにする。
   ・RPLK・LPRK・WPLK などの続け書きは、攻撃が2回以上ある技（例：水芭蕉 ＝ RP のあとに LK）は別々のアイコン（順番押し）、
     攻撃が1回だけの技（ヒートバースト・投げ・ヒートスマッシュなど）や挑発・気合溜めのような攻撃のない動作は、これまでどおり同時押しのアイコンにする。
   ・ボタンが続いているだけのもの（LP と RP など、同時押しにならない組み合わせ）は、いつも別々のアイコン。
   renderCmd 自体は変えない（コンボ集・アップデート内容は、続けて書いたものを同時押しのアイコンとして使っているため）。 */
const SHEET_BTN = "WPWK|WPRK|WPLK|LPWK|RPWK|LPRK|RPLK|WP|WK|WL|WR|LP|RP|LK|RK";
const SHEET_BTN_RE = new RegExp("(?:" + SHEET_BTN + ")(?:\\+(?:" + SHEET_BTN + "))*", "g");
const SHEET_BTN_HEAD = new RegExp("^(?:" + SHEET_BTN + ")");
const SHEET_NUMS = { LP: "1", RP: "2", LK: "3", RK: "4", WP: "12", WK: "34", WL: "13", WR: "24", LPRK: "14", RPLK: "23", WPLK: "123", WPRK: "124", LPWK: "134", RPWK: "234", WPWK: "1234" };
