function charProgress(c) {
  let d = 0, t = 0;
  c.moves.forEach((raw, idx) => {
    const i = moveId(raw, idx);
    const off = (typeof raw === "object" && raw.off) || [];
    COLS.forEach(col => { if (!off.includes(col.id)) { t++; if (state[key(c.id, i, col.id)]) d++; } });
  });
  return { d, t };
}
/* キャラの絵（一覧・ヘッダーの顔・トップの絵）は、右クリックや長押しの「画像をコピー」「画像を保存」、ドラッグ、選択してのコピーで取り出せないようにする。
   絵に当たる操作（右クリック・長押しのメニュー・ドラッグ）を止め、全部選んでコピーしても、絵は入れず、文字だけをコピーする。文字のコピー、ふつうの長押しは止めない */
const PIC_SEL = ".th, .chbtn, .chr";
function inPic(e) {
  const p = e.composedPath ? e.composedPath() : [e.target];
  return p.some(n => n && n.nodeType === 1 && n.matches && n.matches(PIC_SEL));
}
["contextmenu", "dragstart"].forEach(t => document.addEventListener(t, e => { if (inPic(e)) e.preventDefault(); }, true));
document.addEventListener("copy", e => {
  if (!e.clipboardData || !window.getSelection) return;
  const s = window.getSelection();
  if (!s || s.isCollapsed || !s.rangeCount) return;
  const touch = n => { for (let i = 0; i < s.rangeCount; i++) { try { if (s.getRangeAt(i).intersectsNode(n)) return true; } catch (x) {} } return false; };   // 選択の範囲に絵が入っているか（絵は選択できない設定なので、containsNode ではなく範囲そのもので調べる）
  const hit = [...document.querySelectorAll("img.th, #hoHost")].some(touch);   // 上の顔・キャラ選択の一覧の顔、トップの大きな絵（#hoHost の中）
  if (hit) { e.preventDefault(); e.clipboardData.setData("text/plain", String(s)); }
}, true);
function renderChars() {
  const grid = $("chargrid"); grid.innerHTML = "";
  const q = norm($("cq").value.trim());
  CHARACTERS.forEach(c => {
    if (q && !norm(c.name).includes(q) && !norm(c.en).includes(q)) return;
    const { d, t } = charProgress(c);
    const pct = t ? Math.round(d / t * 100) : 0;
    const b = document.createElement("button");
    b.type = "button"; b.className = "chbtn"; b.setAttribute("aria-pressed", String(c.id === current));
    b.innerHTML = '<span class="n"></span><span class="bar"><i></i></span><span class="p"></span>';
    if (c.img) { const im = document.createElement("img"); im.className = "th"; im.alt = ""; im.draggable = false; im.src = c.img; b.prepend(im); }
    b.querySelector(".n").textContent = c.name;
    { const nrv = rvCount(c); if (nrv) b.dataset.rv = nrv; }   // ブックマークの数
    b.querySelector(".bar i").style.width = pct + "%";
    const p = b.querySelector(".p");
    p.textContent = t ? pct + "%" : "未登録"; if (t && d === t) p.classList.add("full");
    b.onclick = () => { selectChar(c.id); closeSheets(); };
    grid.appendChild(b);
  });
  if (!grid.firstChild) grid.innerHTML = '<div class="empty" style="grid-column:1/-1">該当するキャラがいません。</div>';
}
$("charBtn").onclick = () => { $("cq").value = ""; renderChars(); showSheet($("charSheet")); };
$("cq").addEventListener("input", renderChars);
{   // ドロワーを左へ払うと閉じる
  const cs = $("charSheet"); let sx = 0, sy = 0, on = false;
  cs.addEventListener("touchstart", e => { const t = e.touches[0]; sx = t.clientX; sy = t.clientY; on = e.touches.length === 1; }, { passive: true });
  cs.addEventListener("touchmove", e => { if (!on) return; const t = e.touches[0]; if (t.clientX - sx < -70 && Math.abs(t.clientY - sy) < 40) { on = false; closeSheets(); } }, { passive: true });
}

function selectChar(id) {
  current = id; save(); opened.clear();
  if (openedBeforeAns) openedBeforeAns = new Set();   // キャラが変わったので、OFFにしたときに戻す「開いていたカード」は無し
  buildMoves(); renderTop(); renderList();
  if (window.onCharChanged) window.onCharChanged();   // コンボ集も、いま選んでいるキャラに合わせる
  window.scrollTo({ top: 0 });
}

